describe('Lazy-loaded components', () => {
    beforeEach(() => {
        cy.visit('/your-page-url'); // Replace with the actual URL of the page
    });

    it('should display lazy-loaded components smoothly without layout shift', () => {
        cy.get('.lazy-load-trigger').scrollIntoView(); // Trigger lazy loading
        cy.get('.lazy-loaded-component').should('be.visible').and('have.class', 'fade-in'); // Check visibility and animation class
        cy.get('.layout-element').should('have.css', 'transition', 'all 0.3s ease'); // Ensure layout transition
    });

    it('should not cause layout shift when lazy-loaded component appears', () => {
        cy.get('.layout-element').then(($el) => {
            const initialHeight = $el.outerHeight(); // Get initial height
            cy.get('.lazy-load-trigger').scrollIntoView(); // Trigger lazy loading
            cy.get('.lazy-loaded-component').should('be.visible'); // Ensure component is visible
            cy.get('.layout-element').should(($el) => {
                const newHeight = $el.outerHeight(); // Get new height
                expect(newHeight).to.eq(initialHeight); // Check that height remains the same
            });
        });
    });
});
